public class ChuteGameTests {
    private static final BlockPos P=new BlockPos(3,4,3);
    private static ChuteBlockEntity chute(GameTestHelper h,BlockPos pos){h.setBlock(pos,AllBlocks.CHUTE);return h.getBlockEntity(pos,ChuteBlockEntity.class);}
    private static SmartChuteBlockEntity smart(GameTestHelper h){h.setBlock(P,AllBlocks.SMART_CHUTE.defaultBlockState().setValue(SmartChuteBlock.POWERED,false));return h.getBlockEntity(P,SmartChuteBlockEntity.class);}
    private static ChestBlockEntity chest(GameTestHelper h,BlockPos pos){h.setBlock(pos,Blocks.CHEST);return h.getBlockEntity(pos,ChestBlockEntity.class);}
    private static void tick(ChuteBlockEntity chute,int amount){for(int i=0;i<amount;i++)ChuteBlockEntity.tick(chute.getLevel(),chute.getBlockPos(),chute.getBlockState(),chute);}
    private static long count(GameTestHelper h,BlockPos pos,Item item){try(var tx=Transaction.openOuter()){return FunnelTransfer.find(h.getLevel(),h.absolutePos(pos),Direction.UP).extract(ItemVariant.of(item),100000,tx);}}
    private static EncasedFanBlockEntity fan(GameTestHelper h,BlockPos pos,Direction facing,int speed){h.setBlock(pos,AllBlocks.ENCASED_FAN.defaultBlockState().setValue(EncasedFanBlock.FACING,facing));var fan=h.getBlockEntity(pos,EncasedFanBlockEntity.class);fan.setNetworkState(speed,speed,false,new KineticGraph.Stress(100000,0,false),Map.of());return fan;}
    private static void insert(ChuteBlockEntity chute,ItemStack stack){try(var tx=Transaction.openOuter()){if(chute.itemHandler.insert(ItemVariant.of(stack),stack.getCount(),tx)!=stack.getCount())throw new AssertionError("Test cargo not accepted");tx.commit();}}
    private static void refresh(ChuteBlockEntity chute){chute.requestAirflowUpdate();chute.refreshAirflow();}
    @GameTest public void transactionalSlotPreservesComponentsAndDoesNotMergeOrLeakOnAbort(GameTestHelper h){var chute=chute(h,P);var named=new ItemStack(Items.APPLE,12);named.set(DataComponents.CUSTOM_NAME,Component.literal("Owned cargo"));try(var tx=Transaction.openOuter()){chute.itemHandler.insert(ItemVariant.of(named),12,tx);}h.assertTrue(chute.getItem().isEmpty(),"Insertion abort restores empty chute");insert(chute,named);try(var tx=Transaction.openOuter()){h.assertValueEqual(chute.itemHandler.insert(ItemVariant.of(named),1,tx),0L,"Occupied chute never merges");h.assertValueEqual(chute.itemHandler.extract(ItemVariant.of(named),5,tx),5L,"Partial extraction simulated");}h.assertTrue(ItemStack.isSameItemSameComponents(chute.getItem(),named),"Components survive abort");h.assertValueEqual(chute.getItem().getCount(),12,"Stack restored");h.succeed();}
    @GameTest public void ordinaryChuteExtractsSixteenFromInventoryPerBatch(GameTestHelper h){var source=chest(h,P.above());source.setItem(0,new ItemStack(Items.APPLE,40));chest(h,P.below());var chute=chute(h,P);tick(chute,1);h.assertValueEqual(chute.getItem().getCount(),16,"Original extraction amount sixteen");h.assertValueEqual(count(h,P.above(),Items.APPLE),24L,"Only sixteen consumed");h.assertValueEqual(chute.getItemMotion(),-.2f,"Gravity four chutes per second");h.succeed();}
    @GameTest public void gravityColumnTransfersWholeBatchesAndRetainsEveryItem(GameTestHelper h){var source=chest(h,P.above(2));source.setItem(0,new ItemStack(Items.APPLE,20));chest(h,P.below());var lower=chute(h,P);var upper=chute(h,P.above());for(int i=0;i<35;i++){tick(upper,1);tick(lower,1);}h.assertValueEqual(count(h,P.below(),Items.APPLE),20L,"All twenty arrived");h.assertTrue(upper.getItem().isEmpty()&&lower.getItem().isEmpty(),"No queue duplicates");h.assertValueEqual(count(h,P.above(2),Items.APPLE),0L,"Source empty");h.succeed();}
    @GameTest public void exactSmartExtractionWaitsAndCombinesMatchingInventorySlots(GameTestHelper h){var source=chest(h,P.above());source.setItem(0,new ItemStack(Items.APPLE,3));source.setItem(1,new ItemStack(Items.APPLE,4));chest(h,P.below());var chute=smart(h);chute.filtering.setAmount(8,false);tick(chute,1);h.assertTrue(chute.getItem().isEmpty(),"Seven is insufficient");source.setItem(2,new ItemStack(Items.APPLE,2));tick(chute,1);h.assertValueEqual(chute.getItem().getCount(),8,"Exact batch combined across slots");h.assertValueEqual(count(h,P.above(),Items.APPLE),1L,"Remainder stays at source");h.succeed();}
    @GameTest public void smartFilterRejectsUnlistedInputAndUsesConfiguredUpToLimit(GameTestHelper h){var source=chest(h,P.above());source.setItem(0,new ItemStack(Items.CARROT,12));source.setItem(1,new ItemStack(Items.APPLE,12));chest(h,P.below());var chute=smart(h);chute.filtering.setFilter(FilterGameTests.filter(false,false,new ItemStack(Items.APPLE)));chute.filtering.setAmount(5,true);tick(chute,1);h.assertTrue(chute.getItem().is(Items.APPLE),"Allowed item chosen");h.assertValueEqual(chute.getItem().getCount(),5,"Up-to limit five");h.assertValueEqual(count(h,P.above(),Items.CARROT),12L,"Rejected stack retained");h.succeed();}
    @GameTest public void poweredSmartChuteBlocksInsertionAndOutputWhileAutomationCanRecoverItem(GameTestHelper h){chest(h,P.below());var chute=smart(h);insert(chute,new ItemStack(Items.APPLE,12));h.setBlock(P,chute.getBlockState().setValue(SmartChuteBlock.POWERED,true));tick(chute,10);h.assertValueEqual(count(h,P.below(),Items.APPLE),0L,"Power blocks output");h.assertValueEqual(chute.getItem().getCount(),12,"Queue retained");try(var tx=Transaction.openOuter()){h.assertValueEqual(chute.itemHandler.extract(ItemVariant.of(Items.APPLE),12,tx),12L,"Automation may recover powered cargo");tx.commit();}try(var tx=Transaction.openOuter()){h.assertValueEqual(chute.itemHandler.insert(ItemVariant.of(Items.APPLE),1,tx),0L,"Power blocks new input");}h.succeed();}
    @GameTest public void collectingFromAnotherChuteIgnoresSmartExtractionCount(GameTestHelper h){chest(h,P.below());var lower=smart(h);var upper=chute(h,P.above());lower.filtering.setAmount(32,false);h.assertFalse(lower.filtering.isCountVisible(),"Count hidden under upstream chute");insert(upper,new ItemStack(Items.APPLE,7));for(int i=0;i<8;i++){tick(upper,1);tick(lower,1);}h.assertValueEqual(count(h,P.below(),Items.APPLE)+lower.getItem().getCount(),7L,"Seven accepted despite exact thirty-two");h.succeed();}
    @GameTest public void blockedPartialOutputRetainsRemainderWithoutDuplication(GameTestHelper h){var out=chest(h,P.below());for(int i=0;i<27;i++)out.setItem(i,new ItemStack(Items.APPLE,i==0?63:64));var chute=chute(h,P);insert(chute,new ItemStack(Items.APPLE,8));tick(chute,12);h.assertValueEqual(count(h,P.below(),Items.APPLE),27L*64,"One free slot filled");h.assertValueEqual(chute.getItem().getCount(),7,"Seven waiting");out.setItem(0,ItemStack.EMPTY);tick(chute,10);h.assertTrue(chute.getItem().isEmpty(),"Queue released after capacity returns");h.assertValueEqual(count(h,P.below(),Items.APPLE),26L*64+7,"Remaining seven delivered exactly once");h.succeed();}
    @GameTest public void diagonalTransfersToItsLowerTargetRatherThanDropping(GameTestHelper h){var lower=chute(h,P);chest(h,P.below());var branch=P.above().east();h.setBlock(branch,AllBlocks.CHUTE.defaultBlockState().setValue(ChuteBlock.FACING,Direction.EAST).setValue(ChuteBlock.SHAPE,ChuteBlock.Shape.INTERSECTION));var upper=h.getBlockEntity(branch,ChuteBlockEntity.class);insert(upper,new ItemStack(Items.APPLE,9));tick(upper,6);h.assertTrue(lower.getItem().is(Items.APPLE),"Diagonal enters lower target");h.assertValueEqual(lower.getItem().getCount(),9,"Whole stack transferred");h.assertValueEqual(lower.getItemPosition(1),.51f,"Original diagonal entry offset");h.assertTrue(upper.getItem().isEmpty(),"Source cleared");h.succeed();}
    @GameTest public void diagonalWithBlockedTargetRetainsCargoAtItsCentre(GameTestHelper h){var lower=chute(h,P);insert(lower,new ItemStack(Items.CARROT,1));var branch=P.above().east();h.setBlock(branch,AllBlocks.CHUTE.defaultBlockState().setValue(ChuteBlock.FACING,Direction.EAST));var upper=h.getBlockEntity(branch,ChuteBlockEntity.class);insert(upper,new ItemStack(Items.APPLE,9));tick(upper,10);h.assertValueEqual(upper.getItem().getCount(),9,"Blocked source retained");h.assertValueEqual(upper.getItemPosition(1),.5f,"Held at centre");h.succeed();}
    @GameTest public void pullAddsFanSpeedsAcrossBothUpperBranches(GameTestHelper h){var root=chute(h,P);var east=P.above().east();var west=P.above().west();h.setBlock(east,AllBlocks.CHUTE.defaultBlockState().setValue(ChuteBlock.FACING,Direction.EAST));h.setBlock(west,AllBlocks.CHUTE.defaultBlockState().setValue(ChuteBlock.FACING,Direction.WEST));fan(h,east.above(),Direction.DOWN,64);fan(h,west.above(),Direction.DOWN,32);refresh(root);h.assertValueEqual(root.getPull(),96f,"Pull sums across branches");h.assertTrue(Math.abs(root.getItemMotion()-.075f)<1e-6,"Summed upward item motion");h.succeed();}
    @GameTest public void pushSharesBottomFanSpeedAcrossUpperBranches(GameTestHelper h){var root=chute(h,P);var east=P.above().east();var west=P.above().west();h.setBlock(east,AllBlocks.CHUTE.defaultBlockState().setValue(ChuteBlock.FACING,Direction.EAST));h.setBlock(west,AllBlocks.CHUTE.defaultBlockState().setValue(ChuteBlock.FACING,Direction.WEST));fan(h,P.below(),Direction.UP,128);refresh(root);h.assertValueEqual(root.getPush(),128f,"Root gets full fan");h.assertValueEqual(h.getBlockEntity(east,ChuteBlockEntity.class).getPush(),64f,"Half to east");h.assertValueEqual(h.getBlockEntity(west,ChuteBlockEntity.class).getPush(),64f,"Half to west");h.succeed();}
    @GameTest public void opposingFansCancelIntoNormalGravity(GameTestHelper h){var root=chute(h,P);fan(h,P.above(),Direction.DOWN,64);fan(h,P.below(),Direction.UP,-64);refresh(root);h.assertValueEqual(root.getItemMotion(),-.2f,"Zero net airflow keeps gravity");h.succeed();}
    @GameTest public void upwardOutputChoosesFastestAcceptingBranch(GameTestHelper h){var root=chute(h,P);var east=P.above().east();var west=P.above().west();h.setBlock(east,AllBlocks.CHUTE.defaultBlockState().setValue(ChuteBlock.FACING,Direction.EAST));h.setBlock(west,AllBlocks.CHUTE.defaultBlockState().setValue(ChuteBlock.FACING,Direction.WEST));fan(h,east.above(),Direction.DOWN,64);fan(h,west.above(),Direction.DOWN,32);refresh(root);insert(root,new ItemStack(Items.APPLE,11));tick(root,20);h.assertValueEqual(h.getBlockEntity(east,ChuteBlockEntity.class).getItem().getCount(),11,"Faster branch selected");h.assertTrue(h.getBlockEntity(west,ChuteBlockEntity.class).getItem().isEmpty(),"Slower branch untouched");h.succeed();}
    @GameTest public void poweredSmartBranchIsSkippedForAnotherAcceptingRoute(GameTestHelper h){var root=chute(h,P);h.setBlock(P.above(),AllBlocks.SMART_CHUTE.defaultBlockState().setValue(SmartChuteBlock.POWERED,true));var diagonal=P.above().east();h.setBlock(diagonal,AllBlocks.CHUTE.defaultBlockState().setValue(ChuteBlock.FACING,Direction.EAST));fan(h,diagonal.above(),Direction.DOWN,64);refresh(root);insert(root,new ItemStack(Items.APPLE,8));tick(root,25);h.assertValueEqual(h.getBlockEntity(diagonal,ChuteBlockEntity.class).getItem().getCount(),8,"Powered upper path skipped");h.succeed();}
    @GameTest public void suctionLiftsWholeDisplayedDepotStackAtOriginalRange(GameTestHelper h){var root=chute(h,P);fan(h,P.above(),Direction.DOWN,64);h.setBlock(P.below(2),AllBlocks.DEPOT);var depot=h.getBlockEntity(P.below(2),DepotBlockEntity.class);try(var tx=Transaction.openOuter()){depot.inventory.automation.insert(ItemVariant.of(Items.APPLE),17,tx);tx.commit();}refresh(root);tick(root,1);h.assertTrue(root.getBottomPullDistance()>1&&root.getBottomPullDistance()<=2,"Two-block suction is clipped to depot surface");h.assertValueEqual(root.getItem().getCount(),17,"Whole displayed stack lifted");h.assertTrue(depot.getHeldItem().isEmpty(),"Depot and chute handoff atomic");h.assertTrue(root.getItemPosition(1)<0,"Visible travelling item starts below chute");h.succeed();}
    @GameTest public void suctionCannotReachThroughSolidObstruction(GameTestHelper h){var root=chute(h,P);fan(h,P.above(),Direction.DOWN,128);h.setBlock(P.below(),Blocks.STONE);h.setBlock(P.below(2),AllBlocks.DEPOT);var depot=h.getBlockEntity(P.below(2),DepotBlockEntity.class);try(var tx=Transaction.openOuter()){depot.inventory.automation.insert(ItemVariant.of(Items.APPLE),8,tx);tx.commit();}refresh(root);tick(root,10);h.assertTrue(root.getItem().isEmpty(),"Solid block stops pickup");h.assertValueEqual(depot.getHeldItem().getCount(),8,"Depot retained");h.succeed();}
    @GameTest public void suctionCapturesWorldItemWithoutLeavingAnotherCopy(GameTestHelper h){var root=chute(h,P);fan(h,P.above(),Direction.DOWN,128);refresh(root);var at=Vec3.atCenterOf(h.absolutePos(P.below(2)));var entity=new ItemEntity(h.getLevel(),at.x,at.y,at.z,new ItemStack(Items.APPLE,13));h.getLevel().addFreshEntity(entity);tick(root,1);h.assertValueEqual(root.getItem().getCount(),13,"World stack captured");h.assertTrue(entity.isRemoved(),"World copy removed");h.succeed();}
    @GameTest public void positiveFlowCanCaptureAnItemAtItsMouthWithoutLongRangeSuction(GameTestHelper h){var root=chute(h,P);fan(h,P.below(),Direction.UP,128);refresh(root);h.assertValueEqual(root.getBottomPullDistance(),0f,"Bottom fan supplies push without remote suction");var at=Vec3.atCenterOf(h.absolutePos(P)).add(0,-.45,0);var entity=new ItemEntity(h.getLevel(),at.x,at.y,at.z,new ItemStack(Items.APPLE,3));h.getLevel().addFreshEntity(entity);tick(root,1);h.assertValueEqual(root.getItem().getCount(),3,"Source mouth search still accepts nearby item");h.assertTrue(entity.isRemoved(),"World copy consumed once");h.succeed();}
    @GameTest(maxTicks=80) public void fallingItemEntersChuteAndReachesBottomInventory(GameTestHelper h){chest(h,P.below());chute(h,P);h.spawnItem(Items.APPLE,Vec3.atCenterOf(P).add(0,1.5,0));h.succeedWhen(()->h.assertValueEqual(count(h,P.below(),Items.APPLE),1L,"Landing item captured and passed through"));}
    @GameTest public void nativeSaveRestoresItemComponentsPositionAndSmartSettings(GameTestHelper h){chest(h,P.above());var root=smart(h);root.filtering.setFilter(new ItemStack(Items.APPLE));root.filtering.setAmount(9,false);var stack=new ItemStack(Items.APPLE,9);stack.set(DataComponents.CUSTOM_NAME,Component.literal("Named shipment"));root.setItem(stack,.37f);var restored=(SmartChuteBlockEntity)BlockEntity.loadStatic(root.getBlockPos(),root.getBlockState(),root.saveWithFullMetadata(h.getLevel().registryAccess()),h.getLevel().registryAccess());h.assertTrue(ItemStack.isSameItemSameComponents(restored.getItem(),stack),"Components restored");h.assertValueEqual(restored.getItemPosition(1),.37f,"Animation position restored");h.assertValueEqual(restored.filtering.count,9,"Count restored");h.assertFalse(restored.filtering.upTo,"Exact mode restored");h.succeed();}
    @GameTest public void unloadingNeverDropsButDestructionReturnsQueueAndInstalledFilter(GameTestHelper h){var root=smart(h);root.filtering.setFilter(FilterGameTests.filter(false,false,new ItemStack(Items.APPLE)));root.setItem(new ItemStack(Items.APPLE,13));root.setRemoved();root.clearRemoved();h.assertTrue(h.getLevel().getEntitiesOfClass(ItemEntity.class,new AABB(h.absolutePos(P)).inflate(1)).isEmpty(),"Unload no drops");h.setBlock(P,Blocks.AIR);var drops=h.getLevel().getEntitiesOfClass(ItemEntity.class,new AABB(h.absolutePos(P)).inflate(1));h.assertValueEqual(drops.stream().filter(item->item.getItem().is(Items.APPLE)).mapToInt(item->item.getItem().getCount()).sum(),13,"One cargo drop");h.assertValueEqual(drops.stream().filter(item->item.getItem().is(AllItems.FILTER)).mapToInt(item->item.getItem().getCount()).sum(),1,"One installed filter drop");h.succeed();}
    @GameTest public void directBeltInputClosesWhenAnotherChuteCoversItsOpening(GameTestHelper h){var root=chute(h,P);tick(root,1);var input=BlockEntityBehaviour.get(root,com.simibubi.create.content.kinetics.belt.behaviour.DirectBeltInputBehaviour.TYPE);h.assertTrue(input.canInsertFromSide(Direction.UP),"Open chute accepts direct input");chute(h,P.above());tick(root,1);h.assertFalse(input.canInsertFromSide(Direction.UP),"Covered opening refuses direct input");h.succeed();}
    @GameTest public void filterPacketsSupportSmartChuteAndRejectHiddenSidesAndOutOfRangeValues(GameTestHelper h){chest(h,P.above());var root=smart(h);var player=h.makeMockPlayer(GameType.SURVIVAL);var pos=h.absolutePos(P);player.setPos(Vec3.atCenterOf(pos).add(0,0,2));h.assertTrue(FilteringSettings.apply(h.getLevel(),player,new FilteringSettings.SetFilter(pos,Direction.SOUTH,InteractionHand.MAIN_HAND,12,false)),"Shared board applies chute amount");h.assertValueEqual(root.filtering.count,12,"Count stored");h.assertFalse(FilteringSettings.apply(h.getLevel(),player,new FilteringSettings.SetFilter(pos,Direction.UP,InteractionHand.MAIN_HAND,5,true)),"Top side hidden");h.assertFalse(FilteringSettings.apply(h.getLevel(),player,new FilteringSettings.SetFilter(pos,Direction.SOUTH,InteractionHand.MAIN_HAND,65,true)),"Oversized count rejected");h.succeed();}
    @GameTest public void itemPlacedAgainstChuteCreatesRaisedDiagonalAndConsumesOne(GameTestHelper h){chute(h,P);var player=h.makeMockPlayer(GameType.SURVIVAL);player.setPos(Vec3.atCenterOf(h.absolutePos(P)).add(2,0,0));player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(AllBlocks.CHUTE,2));var at=h.absolutePos(P);var hit=new BlockHitResult(new Vec3(at.getX()+1,at.getY()+.5,at.getZ()+.5),Direction.EAST,at,false);var result=player.getMainHandItem().useOn(new UseOnContext(player,InteractionHand.MAIN_HAND,hit));h.assertTrue(result.consumesAction(),"Placement succeeded");var state=h.getBlockState(P.above().east());h.assertTrue(state.is(AllBlocks.CHUTE)&&state.getValue(ChuteBlock.FACING)==Direction.EAST,"Raised diagonal points away from target");h.assertValueEqual(player.getMainHandItem().getCount(),1,"One chute consumed");h.succeed();}
    @GameTest public void suctionTakesSpecificBeltCargoWithoutConsumingAdjacentStacks(GameTestHelper h){
        var start=P.below(2).west();var end=start.east(3);var marker=UUID.randomUUID();
        chuteBeltDiagnostics(h,"entry-before-any-new-cargo",marker,null,null);
        h.setBlock(start,AllBlocks.SHAFT.defaultBlockState().setValue(com.simibubi.create.content.kinetics.simpleRelays.ShaftBlock.AXIS,Direction.Axis.Z));
        h.setBlock(end,AllBlocks.SHAFT.defaultBlockState().setValue(com.simibubi.create.content.kinetics.simpleRelays.ShaftBlock.AXIS,Direction.Axis.Z));
        h.assertTrue(com.simibubi.create.content.kinetics.belt.item.BeltConnectorItem.createBelts(h.getLevel(),h.absolutePos(start),h.absolutePos(end)),"Suction test belt created");
        var belt=h.getBlockEntity(start,com.simibubi.create.content.kinetics.belt.BeltBlockEntity.class);
        chuteBeltDiagnostics(h,"belt-created-before-new-cargo",marker,belt,null);
        var named=new ItemStack(Items.APPLE,17);named.set(DataComponents.CUSTOM_NAME,Component.literal("Lift me "+marker));
        try(var tx=Transaction.openOuter()){
            h.assertValueEqual(belt.getInventory().segment(1,Direction.UP).insert(ItemVariant.of(named),17,tx),17L,"Whole current-run target cargo inserted");
            h.assertValueEqual(belt.getInventory().segment(3,Direction.UP).insert(ItemVariant.of(Items.CARROT),9,tx),9L,"Whole neighbouring stack inserted");
            tx.commit();
        }
        chuteBeltDiagnostics(h,"new-cargo-committed",marker,belt,null);
        var root=chute(h,P);fan(h,P.above(),Direction.DOWN,128);
        chuteBeltDiagnostics(h,"chute-and-fan-created",marker,belt,root);
        refresh(root);chuteBeltDiagnostics(h,"airflow-refreshed-before-capture",marker,belt,root);
        tick(root,1);chuteBeltDiagnostics(h,"after-one-real-chute-tick",marker,belt,root);
        h.assertTrue(ItemStack.isSameItemSameComponents(root.getItem(),named),"Current-run component-bearing cargo lifted; marker="+marker+", actual="+chuteBeltStack(root.getItem()));
        h.assertValueEqual(root.getItem().getCount(),17,"Whole target cargo");
        h.assertValueEqual(belt.getInventory().getTransportedItems().stream().mapToInt(item->item.stack.getCount()).sum(),9,"Only neighbouring stack retained");h.succeed();
    }

    /** Read-only diagnostics: keep source/cargo assertions intact and distinguish retained-world items. */
    private static void chuteBeltDiagnostics(GameTestHelper h,String stage,UUID marker,com.simibubi.create.content.kinetics.belt.BeltBlockEntity original,ChuteBlockEntity root){
        var level=h.getLevel();var start=h.absolutePos(P.below(2).west());var nativeStart=level.getBlockEntity(start);
        var loadedStart=com.simibubi.create.foundation.utility.LoadedLevelAccess.blockEntity(level,start);
        var manager=((com.simibubi.create.foundation.mixin.accessor.ServerLevelEntityManagerAccessor)level).create$getEntityManager();
        var visibility=((com.simibubi.create.foundation.mixin.accessor.EntitySectionVisibilityAccessor)manager).create$getChunkVisibility();
        var loadState=(com.simibubi.create.test.mixin.GameTestEntityLoadStateAccessor)manager;
        var chunks=new LinkedHashMap<String,String>();var segments=new ArrayList<String>();
        for(int index=0;index<4;index++){
            var pos=start.east(index);long key=net.minecraft.world.level.ChunkPos.pack(pos);var chunk=level.getChunkSource().getChunkNow(pos.getX()>>4,pos.getZ()>>4);
            chunks.put(new net.minecraft.world.level.ChunkPos(pos.getX()>>4,pos.getZ()>>4).toString(),"cached="+(chunk!=null)+", full="+(chunk==null?null:chunk.getFullStatus())+", loaded="+level.areEntitiesLoaded(key)+", visibility="+visibility.get(key)+", visibilityEntry="+visibility.containsKey(key)+", loadStatus="+loadState.create$testEntityLoadStatuses().get(key));
            var actual=level.getBlockEntity(pos);var cached=com.simibubi.create.foundation.utility.LoadedLevelAccess.blockEntity(level,pos);
            segments.add("segment="+index+", native="+chuteBeltEntity(actual)+", cached="+chuteBeltEntity(cached)+", same="+(actual==cached));
        }
        var centre=Vec3.atCenterOf(h.absolutePos(P));float distance=root==null?3:root.getBottomPullDistance();
        var suction=new AABB(centre.add(0,-distance-.5,0),centre.add(0,-.5,0)).inflate(.45);
        var worldItems=level.getEntitiesOfClass(ItemEntity.class,suction.inflate(2)).stream().map(entity->"uuid="+entity.getUUID()+", pos="+entity.position()+", alive="+entity.isAlive()+", inSuction="+suction.intersects(entity.getBoundingBox())+", "+chuteBeltStack(entity.getItem())).toList();
        var controller=loadedStart instanceof com.simibubi.create.content.kinetics.belt.BeltBlockEntity belt?belt.getControllerBE():null;
        Create.LOGGER.info("Chute specific-belt diagnostic: stage={}, marker={}, gameTime={}, source={}, original={}, nativeStart={}, cachedStart={}, originalIsNative={}, originalIsCached={}, liveController={}, originalIsController={}, root={}, suction={}, chunks={}, segments={}, worldItems={}",
                stage,marker,level.getGameTime(),start,chuteBeltEntity(original),chuteBeltEntity(nativeStart),chuteBeltEntity(loadedStart),original==nativeStart,original==loadedStart,chuteBeltEntity(controller),original==controller,
                root==null?null:chuteBeltStack(root.getItem())+", position="+root.getItemPosition(1),suction,chunks,segments,worldItems);
    }
    private static String chuteBeltEntity(BlockEntity entity){
        if(entity==null)return "null";var description=entity.getClass().getSimpleName()+"@"+Integer.toHexString(System.identityHashCode(entity))+", pos="+entity.getBlockPos()+", removed="+entity.isRemoved();
        if(entity instanceof com.simibubi.create.content.kinetics.belt.BeltBlockEntity belt)description+=", controller="+belt.getController()+", isController="+belt.isController()+", index="+belt.index+", length="+belt.beltLength+", cargo="+belt.getInventory().getTransportedItems().stream().map(cargo->"uuid="+cargo.id+", position="+cargo.beltPosition+", "+chuteBeltStack(cargo.stack)).toList();
        return description;
    }
    private static String chuteBeltStack(ItemStack stack){return "item="+net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(stack.getItem())+", count="+stack.getCount()+", customName="+stack.get(DataComponents.CUSTOM_NAME)+", components="+stack.getComponentsPatch();}
    @GameTest(maxTicks=35) public void realRedstoneSignalPausesAndResumesSmartChute(GameTestHelper h){
        chest(h,P.below());var root=smart(h);h.setBlock(P.south(),Blocks.REDSTONE_BLOCK);
        h.runAfterDelay(3,()->{h.assertTrue(root.getBlockState().getValue(SmartChuteBlock.POWERED),"Native neighbour signal activates pause");root.setItem(new ItemStack(Items.APPLE,8),.5f);});
        h.runAfterDelay(10,()->{h.assertValueEqual(root.getItem().getCount(),8,"Cargo paused under signal");h.assertValueEqual(count(h,P.below(),Items.APPLE),0L,"No paused output");h.setBlock(P.south(),Blocks.AIR);});
        h.succeedWhen(()->{h.assertTrue(h.getTick()>10,"Wait for signal removal");h.assertValueEqual(count(h,P.below(),Items.APPLE),8L,"Resumed cargo delivered");});
    }
    @GameTest public void windowAndEncasingKeepCargoAndUseOriginalSampleSemantics(GameTestHelper h){
        var root=chute(h,P);root.setItem(new ItemStack(Items.APPLE,7),.5f);var player=h.makeMockPlayer(GameType.SURVIVAL);var at=h.absolutePos(P);var hit=new BlockHitResult(Vec3.atCenterOf(at).add(0,0,.5),Direction.SOUTH,at,false);player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(AllBlocks.INDUSTRIAL_IRON_BLOCK,2));var result=h.getBlockState(P).useItemOn(player.getMainHandItem(),h.getLevel(),player,InteractionHand.MAIN_HAND,hit);h.assertTrue(result.consumesAction(),"Industrial iron casing sample accepted");h.assertValueEqual(h.getBlockState(P).getValue(ChuteBlock.SHAPE),ChuteBlock.Shape.ENCASED,"Encased state");h.assertValueEqual(player.getMainHandItem().getCount(),2,"Source encasing sample not consumed");player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(AllItems.WRENCH));var context=new UseOnContext(player,InteractionHand.MAIN_HAND,hit);AllBlocks.CHUTE.onWrenched(h.getBlockState(P),context);AllBlocks.CHUTE.onWrenched(h.getBlockState(P),context);h.assertValueEqual(h.getBlockState(P).getValue(ChuteBlock.SHAPE),ChuteBlock.Shape.WINDOW,"Wrench opens window");h.assertValueEqual(root.getItem().getCount(),7,"Shape change preserves cargo");h.succeed();
    }
    @GameTest(maxTicks=90) public void realDrivenFanLiftsCargoThroughVerticalColumn(GameTestHelper h){var lower=chute(h,P);chute(h,P.above());var fanPos=P.above(2);h.setBlock(fanPos,AllBlocks.ENCASED_FAN.defaultBlockState().setValue(EncasedFanBlock.FACING,Direction.DOWN));h.setBlock(fanPos.above(),AllBlocks.CREATIVE_MOTOR.defaultBlockState().setValue(CreativeMotorBlock.FACING,Direction.DOWN));h.getBlockEntity(fanPos.above(),KineticBlockEntity.class).setGeneratedSpeed(-128);insert(lower,new ItemStack(Items.APPLE,7));h.succeedWhen(()->{h.assertValueEqual(lower.getPull(),128f,"Driven fan pull reaches lower chute");h.assertValueEqual(h.getBlockEntity(P.above(),ChuteBlockEntity.class).getItem().getCount(),7,"Cargo lifted into upper chute");});}
}
